int get_bitmap_file(struct mddev *mddev, void __user *arg)
{
    struct bitmap_file *bf;
    int ret = 0;

    bf = kmalloc(sizeof(*bf), GFP_KERNEL);
    if (!bf)
        return -ENOMEM;

    if (!mddev->bitmap) {
        bf->pathname[0] = '\0';
    } else {
        const char *path = mddev->bitmap->filename;

        if (!path || strlen(path) >= PATH_MAX) {
            ret = -EINVAL;
            goto out;
        }

        strncpy(bf->pathname, path, PATH_MAX);
        bf->pathname[PATH_MAX - 1] = '\0';
    }

    if (copy_to_user(arg, bf, sizeof(*bf)))
        ret = -EFAULT;

out:
    kfree(bf);
    return ret;
}

int get_bitmap_file(struct mddev *mddev, void __user *arg) {
    struct bitmap_file {
        char pathname[BDEVNAME_SIZE];
    } *bf;
    int ret = -ENOMEM;

    bf = kmalloc(sizeof(*bf), GFP_KERNEL);
    if (!bf)
        goto out;

    if (!test_bit(Bitmap_present, &mddev->flags)) {
        bf->pathname[0] = '\0';
    } else {
        char bname[BDEVNAME_SIZE];

        if (!mddev->bitmap) {
            ret = -EINVAL;
            goto out_free;
        }

        bdevname(mddev->bitmap->file->bdev, bname);
        snprintf(bf->pathname, sizeof(bf->pathname), "%s", bname);
    }

    if (copy_to_user(arg, bf, sizeof(*bf)))
        ret = -EFAULT;
    else
        ret = 0;

out_free:
    kfree(bf);
out:
    return ret;
}

int get_bitmap_file(struct mddev *mddev, void __user *arg)
{
    struct bitmap_file *bf;
    int ret = 0;

    bf = kmalloc(sizeof(*bf), GFP_KERNEL);
    if (!bf)
        return -ENOMEM;

    if (!mddev->bitmap)
        bf->pathname[0] = '\0';
    else
        strlcpy(bf->pathname, mddev->bitmap->file_path, sizeof(bf->pathname));

    if (copy_to_user(arg, bf, sizeof(*bf))) {
        ret = -EFAULT;
    }

    kfree(bf);
    return ret;
}
